package net.civeira.phylax.feature.identity.consentpurpose.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.feature.identity.consentpurpose.domain.valueobject.TitleVO;

class TitleValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of title of consent purpose")
  void test_title_value_holder_assign_plain_value() {
    Object holder = new Object();
    TitleValueHolder<Object> value = new TitleValueHolder<>(holder);
    Assertions.assertSame(holder, value.title("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTitleValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getTitle().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of title of consent purpose")
  void test_title_value_holder_assign_value_object() {
    Object holder = new Object();
    TitleValueHolder<Object> value = new TitleValueHolder<>(holder);
    TitleVO vo = TitleVO.from("one");
    Assertions.assertFalse(value.getTitleValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.title(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTitleValue().orElseThrow());
    Assertions.assertSame(holder, value.title(Optional.empty()));
    Assertions.assertFalse(value.getTitleValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.title(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTitleValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of title of consent purpose against the original")
  void test_title_value_holder_read() {
    Object holder = new Object();
    TitleValueHolder<Object> value = new TitleValueHolder<>(holder);
    TitleVO vo = TitleVO.from("one");
    TitleVO other = TitleVO.from("one");
    ConsentPurpose original = Mockito.mock(ConsentPurpose.class);
    Mockito.when(original.getTitleValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTitle(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTitle(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.title(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTitle(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTitle(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of title of consent purpose")
  void test_title_value_holder_unset() {
    Object holder = new Object();
    TitleValueHolder<Object> value = new TitleValueHolder<>(holder);
    TitleVO vo = TitleVO.from("one");
    value.title(vo);
    Assertions.assertSame(holder, value.unsetTitleIfMatches("title_other"));
    Assertions.assertTrue(value.getTitleValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTitleIfMatches("title"));
    Assertions.assertFalse(value.getTitleValue().isPresent(),
        "The field name must clear the value");
    value.title(vo);
    Assertions.assertSame(holder, value.unsetTitle());
    Assertions.assertFalse(value.getTitleValue().isPresent(), "Unset must clear the value");
  }
}
